-- Demo (placeholder) vehicles so you can test bookings with your own phone.
-- 2 matatus per direction on every route + a few Ndai cars and bodas. Clearly labelled DEMO in the app.
create table if not exists public.demo_vehicles (
  id text primary key,
  kind text not null default 'matatu' check (kind in ('matatu','car','boda')),
  route_id text,
  direction text check (direction in ('forward','reverse')),
  plate text not null,
  label text,
  seats_total int not null default 14 check (seats_total >= 1),
  seats_taken int not null default 0 check (seats_taken >= 0),
  speed_kmh real not null default 22,
  phase real not null default 0,
  lat double precision,
  lon double precision,
  active boolean not null default true
);
create index if not exists demo_vehicles_route_idx on public.demo_vehicles(route_id, direction);
alter table public.demo_vehicles enable row level security;
drop policy if exists "Anyone can see demo vehicles" on public.demo_vehicles;
create policy "Anyone can see demo vehicles" on public.demo_vehicles for select to anon, authenticated using (active);
revoke all on public.demo_vehicles from public, anon, authenticated;
grant select on public.demo_vehicles to anon, authenticated;

create table if not exists public.demo_bookings (
  id uuid primary key default gen_random_uuid(),
  vehicle_id text not null references public.demo_vehicles(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  board_stop text,
  seats int not null default 1 check (seats between 1 and 4),
  status text not null default 'booked' check (status in ('booked','cancelled')),
  created_at timestamptz not null default now()
);
alter table public.demo_bookings enable row level security;
drop policy if exists "People see their own demo bookings" on public.demo_bookings;
create policy "People see their own demo bookings" on public.demo_bookings for select to authenticated using (user_id = auth.uid());
revoke all on public.demo_bookings from public, anon, authenticated;
grant select on public.demo_bookings to authenticated;

create or replace function public.demo_book_seat(p_vehicle_id text, p_seats int, p_board_stop text)
returns public.demo_bookings language plpgsql security definer set search_path = public as $$
declare v public.demo_vehicles; b public.demo_bookings;
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  if p_seats < 1 or p_seats > 4 then raise exception 'Choose 1 to 4 seats'; end if;
  select * into v from public.demo_vehicles where id = p_vehicle_id and active for update;
  if not found then raise exception 'Vehicle not found'; end if;
  if v.seats_taken + p_seats > v.seats_total then raise exception 'Not enough seats left'; end if;
  update public.demo_vehicles set seats_taken = seats_taken + p_seats where id = p_vehicle_id;
  return b;
end $$;
revoke all on function public.demo_book_seat(text,int,text) from public, anon;
grant execute on function public.demo_book_seat(text,int,text) to authenticated;

create or replace function public.demo_cancel_booking(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare b public.demo_bookings;
begin
  select * into b from public.demo_bookings where id = p_id and user_id = auth.uid() and status = 'booked' for update;
  if not found then return; end if;
  update public.demo_bookings set status = 'cancelled' where id = p_id;
  update public.demo_vehicles set seats_taken = greatest(0, seats_taken - b.seats) where id = b.vehicle_id;
end $$;
revoke all on function public.demo_cancel_booking(uuid) from public, anon;
grant execute on function public.demo_cancel_booking(uuid) to authenticated;

on conflict (id) do nothing;
